<?php
declare(strict_types=1);namespace App\Services;use PDO;
final class AccountabilityService {public function __construct(private PDO $db){}public function dashboard(int $tid):array{$tables=['teams'=>'team_tournament_entries','athletes'=>'registrations','matches'=>'matches','news'=>'news_posts','documents'=>'documents','galleries'=>'galleries','suspensions'=>'suspensions'];$out=[];foreach($tables as$key=>$table){$sql=$table==='team_tournament_entries'?'SELECT COUNT(*) FROM team_tournament_entries WHERE tournament_id=? AND deleted_at IS NULL':($table==='registrations'?'SELECT COUNT(*) FROM registrations WHERE tournament_id=? AND registration_type="athlete" AND deleted_at IS NULL':"SELECT COUNT(*) FROM `$table` WHERE tournament_id=? AND deleted_at IS NULL");$s=$this->db->prepare($sql);$s->execute([$tid]);$out[$key]=(int)$s->fetchColumn();}$s=$this->db->prepare('SELECT COALESCE(SUM(home_score+away_score),0) FROM matches WHERE tournament_id=? AND status IN ("homologated","walkover") AND deleted_at IS NULL');$s->execute([$tid]);$out['goals']=(int)$s->fetchColumn();$s=$this->db->prepare('SELECT COUNT(*) FROM match_events e JOIN matches m ON m.id=e.match_id WHERE m.tournament_id=? AND e.event_type IN ("yellow","red","second_yellow") AND e.is_cancelled=0');$s->execute([$tid]);$out['cards']=(int)$s->fetchColumn();return$out;}}
